style.css:
@-moz-document domain("youtube.com") {
/* Set background image to tile */
  body {
    background-image: url("https://i.pinimg.com/736x/c5/d2/7e/c5d27e4bd705da2133fe537b881697f1.jpg") !important;
    background-repeat: repeat !important;
    background-attachment: fixed !important;
    background-position: top left !important;
    background-size: auto !important;
  }

  /* Make key containers transparent so the background shows through */
  ytd-app, #page-manager, ytd-watch-flexy, ytd-browse, tp-yt-app-drawer {
    background-color: transparent !important;
    background: none !important;
  }

  /* Optional: dim overlays slightly for readability */
  ytd-masthead, #guide, #chips-wrapper {
    background-color: rgba(255, 255, 255, 0.7) !important;
  }
}
